async function renderStaffRoster(){const root=document.getElementById('portalStaffDirectory')||document.querySelector('[data-staff-section="round"]');if(!root)return;let roster=document.getElementById('staffRoster');if(!roster){roster=document.createElement('section');roster.id='staffRoster';root.append(roster);}try{const r=await fetch(document.getElementById('portalStaffDirectory')?'/api/staff-directory':'/api/portal/staff-roster',{credentials:'same-origin'}),d=await r.json();if(!r.ok)throw Error(d.error||'Roster unavailable.');roster.replaceChildren();const header=document.createElement('div');header.className='staff-roster-heading';const h=document.createElement('h3'),p=document.createElement('p');h.textContent='Command personnel';p.textContent=d.staff.length+' staff members · Official responsibilities · Read-only account registry';header.append(h,p);roster.append(header);const grid=document.createElement('div');grid.className='staff-roster-grid';for(const member of d.staff){const card=document.createElement('article');card.className='staff-personnel-card';card.dataset.role=member.role;const seal=document.createElement('span');seal.className='staff-personnel-seal';seal.textContent={admin:'✦',support:'✉',multihunter:'⌕'}[member.role];const body=document.createElement('div'),title=document.createElement('small'),name=document.createElement('h4'),id=document.createElement('span'),desc=document.createElement('p');title.textContent=member.title;name.textContent=member.username;id.className='staff-personnel-id';id.textContent='ACCOUNT ID '+member.accountId;desc.textContent=member.description;body.append(title,name,id,desc);card.append(seal,body);grid.append(card);}roster.append(grid);}catch(e){roster.textContent=e.message;}}
document.addEventListener('starfall-session-ready',renderStaffRoster);setTimeout(renderStaffRoster,1000);
